import {chromium} from '@playwright/test';
import {writeFileSync} from 'node:fs';
const folder='reference-captures/ordinary-native-867d468';
const browser=await chromium.connectOverCDP('http://127.0.0.1:9227');
const page=browser.contexts().flatMap(c=>c.pages()).find(p=>p.url()==='http://127.0.0.1:3101/');
const proof={started:new Date().toISOString(),scope:'Ordinary public Settings mouse/keyboard input only. Camera zoom is an explicit recreation usability addition; this is not original-size pixel parity or a game-state/seed/clock override.',actions:[],errors:[]};
page.on('pageerror',e=>proof.errors.push(e.message));
try{
 await page.getByRole('dialog',{name:'Paused',exact:true}).waitFor({state:'visible'});
 await page.getByRole('button',{name:'Settings',exact:true}).click();proof.actions.push('Click Settings');
 const settings=page.getByRole('dialog',{name:'Settings',exact:true});
 const slider=settings.getByRole('slider',{name:'Camera zoom',exact:true});
 await slider.waitFor({state:'visible'});proof.before=await slider.getAttribute('aria-valuetext');
 await slider.click();await slider.press('Home');proof.actions.push('Click camera slider; press Home');
 proof.after=await slider.getAttribute('aria-valuetext');
 if(proof.after"'!=='"'50%')throw Error("'`Unexpected public zoom value ${proof.after}`);
 await page.screenshot({path:`${folder}/public-zoom-50.png`});
 await settings.getByRole('"'button',{name:'DONE',exact:true}).click();proof.actions.push('Click DONE');
 await settings.waitFor({state:'hidden'});
 await page.getByRole('dialog',{name:'Paused',exact:true}).waitFor({state:'visible'});
 proof.paused=true;
}catch(error){proof.failure=String(error);throw error;}
finally{proof.ended=new Date().toISOString();writeFileSync("'`${folder}/public-zoom-action.json`,JSON.stringify(proof,null,2)+'"'\\n');await browser.close();}
EOF
node reference-captures/ordinary-native-867d468/set-public-zoom.mjs > reference-captures/ordinary-native-867d468/public-zoom-action.log 2>&1"

